-- IMPO: This module is totally generated by Claude Code, and not tested or reviewed by a human.
-- TODO: Review it!

-- Inlay hints push the rest of their line right, which breaks hand-aligned columns (trailing comments, `=`).
-- This pads the rows with fewer hint cells in front of such a column, until it lines up again.

local CHUNK = 500           -- rows; a group never crosses a multiple of it, which caps how far one redraw looks around
local HL = "FvimHintAlign"  -- tells our padding apart from the hints it shares a namespace with

-- NOTE: Decoration providers run in the order they were first set, and ours measures the hints that
-- \     `vim.lsp.inlay_hint` places in its own `on_win`, so load that module (and its provider) first.
local _ = vim.lsp.inlay_hint
-- HACK: The padding lives in the hints' own namespace: whatever clears the hints takes it along at once,
-- \     so nothing measuring columns right after (like the blockwise workaround in `autocmd.lua`) counts it.
local NS = vim.api.nvim_create_namespace("nvim.lsp.inlayhint")


---Every non-blank character that a run of spaces leads up to, indent excluded, from left to right.
---@param line string
---@return { col: integer, vcol: integer, gap: integer, kind: string }[]
local function anchors(line)
  local list, pos = {}, 1
  -- NOTE: A tab counts as one cell: a column only has to match between rows, and an aligned block shares its indent.
  local plain = not line:find("[\128-\255]")  -- ASCII: one byte, one cell
  while true do
    -- NOTE: A gap holding a tab is no anchor: a tab shrinks to absorb the hint cells in front of it.
    local s, e = line:find("%S +%S", pos)
    if not (s and e) then return list end
    local char = line:sub(e, e)
    list[#list+1] = {
      col = e - 1,
      vcol = plain and e - 1 or vim.api.nvim_strwidth(line:sub(1, e - 1)),
      gap = e - s - 1,
      kind = char:find("[%w_]") and "w" or char,  -- `w` for a word or number
    }
    pos = e
  end
end


---Padding that lines every aligned column back up, as `{ row, col, cells }` per padded anchor.
---@param lines string[] rows from `from` on
---@param from integer
---@param first integer
---@param last integer
---@param hints table<integer, integer[][]> `{ col, cells }` per hint, in column order per row
---@return integer[][]
local function paddings(lines, from, first, last, hints)
  -- STEP1: Chain the anchors at one column on nearby rows into a group, noting the hint cells in front of each.
  -- NOTE: Only alike tokens chain (`--` under `--`, a word under a word), or code that merely happens
  -- \     to reach a comment column would drag the comments along with its hints.
  local groups, open = {}, {}
  for row = first, last do
    local line = lines[row - from + 1]
    if row % CHUNK == 0 or not line:find("%S") then open = {} end
    local hint, k, shift, next_open = hints[row] or {}, 1, 0, {}
    for _, anchor in ipairs(anchors(line)) do
      while hint[k] and hint[k][1] <= anchor.col do shift, k = shift + hint[k][2], k + 1 end
      local group = open[anchor.vcol]
      if not (group and group.kind == anchor.kind) then
        group = { vcol = anchor.vcol, kind = anchor.kind, gap = 0, members = {} }
        groups[#groups+1] = group
      end
      table.insert(group.members, { row = row, col = anchor.col, shift = shift })
      group.gap, group.crossed = math.max(group.gap, anchor.gap), false
      next_open[anchor.vcol] = group
    end
    -- NOTE: A group outlives rows that stop short of its column, and one row that runs across it.
    local reach = vim.api.nvim_strwidth(line:match("^.*%S") or "")
    for vcol, group in pairs(open) do
      if not next_open[vcol] and (reach <= vcol or not group.crossed) then
        group.crossed, next_open[vcol] = group.crossed or reach > vcol, group
      end
    end
    open = next_open
  end

  -- STEP2: An alignment spans 2+ rows, one of which pads its gap. Left to right, each moves as far as
  -- \      its most-pushed row, and the other rows pad up to it.
  local aligned = vim.tbl_filter(function(group) return #group.members > 1 and group.gap > 1 end, groups)
  table.sort(aligned, function(a, b) return a.vcol < b.vcol end)
  local before, result = {}, {}  -- padding a row got at earlier columns, which pushes this one too
  for _, group in ipairs(aligned) do
    local offset = 0
    for _, member in ipairs(group.members) do offset = math.max(offset, member.shift + (before[member.row] or 0)) end
    for _, member in ipairs(group.members) do
      local cells = offset - member.shift - (before[member.row] or 0)
      if cells > 0 then
        result[#result+1] = { member.row, member.col, cells }
        before[member.row] = (before[member.row] or 0) + cells
      end
    end
  end
  return result
end


---Bring the padding up to date on every unit that rows `top` to `bot` touch.
---@param buf integer
---@param top integer 0-indexed
---@param bot integer 0-indexed
local function update(buf, top, bot)
  -- EXIT: No hints in this buffer, so no padding either.
  if not next(vim.api.nvim_buf_get_extmarks(buf, NS, 0, -1, { limit = 1 })) then return end

  -- IMPO: Grow the rows to whole units: runs of non-blank rows, cut at every multiple of `CHUNK`.
  -- \     A row's padding then depends on its unit alone, so windows with different views agree on it;
  -- \     otherwise each would redo the other's padding and redraw it, forever.
  local count = vim.api.nvim_buf_line_count(buf)
  local from = top - top % CHUNK
  local lines = vim.api.nvim_buf_get_lines(buf, from, math.min(bot - bot % CHUNK + CHUNK, count), false)
  local function solid(row) return row >= from and (lines[row - from + 1] or ""):find("%S") end
  local first, last = top, math.min(bot, count - 1)
  while solid(first) and solid(first - 1) do first = first - 1 end
  while solid(last) and solid(last + 1) do last = last + 1 end

  -- STEP1: Sort the marks in range into hints and our padding.
  local hints, placed = {}, {}
  for _, mark in ipairs(vim.api.nvim_buf_get_extmarks(buf, NS, { first, 0 }, { last, -1 }, { details = true })) do
    local row, col, chunks = mark[2], mark[3], mark[4].virt_text or {}
    if chunks[1] and chunks[1][2] == HL then
      local key = row .. ":" .. col
      if placed[key] then vim.api.nvim_buf_del_extmark(buf, NS, mark[1]) else placed[key] = mark end
    else
      local cells = 0
      for _, chunk in ipairs(chunks) do cells = cells + vim.api.nvim_strwidth(chunk[1]) end
      hints[row] = hints[row] or {}
      table.insert(hints[row], { col, cells })
    end
  end

  -- STEP2: Touch only what changed: every extmark change redraws its line.
  for _, pad in ipairs(next(hints) and paddings(lines, from, first, last, hints) or {}) do
    local key, spaces = pad[1] .. ":" .. pad[2], (" "):rep(pad[3])
    local mark = placed[key]
    placed[key] = nil
    if not (mark and mark[4].virt_text[1][1] == spaces) then
      vim.api.nvim_buf_set_extmark(buf, NS, pad[1], pad[2], {
        id = mark and mark[1],
        virt_text = { { spaces, HL } },
        virt_text_pos = "inline",
        hl_mode = "combine",  -- Shows the background underneath, e.g. a selection's, instead of a gap in it.
        priority = 0,         -- Lays out first at its column, so a hint there stays against the text.
      })
    end
  end
  for _, mark in pairs(placed) do vim.api.nvim_buf_del_extmark(buf, NS, mark[1]) end
end


vim.api.nvim_set_decoration_provider(vim.api.nvim_create_namespace("fvim_hint_align"), {
  on_win = function(_, _, buf, top, bot)
    update(buf, top, bot)
    return false
  end,
})
